class Solution {
public:
    string largeOddNum(string& s) {

        int j = -1;

        // Find rightmost odd digit
        for(int i = s.size() - 1; i >= 0; i--) {
            if((s[i] - '0') % 2 == 1) {
                j = i;
                break;
            }
        }

        // No odd digit
        if(j == -1)
            return "";

        // Remove leading zeros
        int i = 0;
        while(i <= j && s[i] == '0') {
            i++;
        }

        return s.substr(i, j - i + 1);
    }
};
